#!/usr/bin/env python3
"""
Merge user data from three sources with different formats and schemas.
Handles field mapping, priority-based conflict resolution, and conflict reporting.
"""

import json
import csv
from datetime import datetime
import pandas as pd
from pathlib import Path
from typing import Dict, List, Tuple, Any


class UserMerger:
    """Merges user data from multiple sources with priority-based conflict resolution."""

    # Field mapping: source field names -> unified field names
    FIELD_MAPPINGS = {
        'user_id': ['user_id', 'id', 'userId'],
        'name': ['name', 'full_name', 'userName'],
        'email': ['email', 'email_address'],
        'created_date': ['created_date', 'registration_date', 'created_at', 'joined'],
        'status': ['status', 'is_active', 'active'],
    }

    SOURCE_PRIORITY = ['source_a', 'source_b', 'source_c']

    def __init__(self):
        self.users: Dict[int, Dict[str, Any]] = {}
        self.source_data: Dict[str, pd.DataFrame] = {}
        self.conflicts: List[Dict[str, Any]] = []

    def read_source_a(self, path: str) -> pd.DataFrame:
        """Read JSON source A."""
        with open(path, 'r') as f:
            data = json.load(f)
        df = pd.DataFrame(data)
        # Rename fields according to mapping
        df = self._map_fields(df, {
            'id': 'user_id',
            'full_name': 'name',
            'email': 'email',
            'registration_date': 'created_date',
        })
        df['source'] = 'source_a'
        return df

    def read_source_b(self, path: str) -> pd.DataFrame:
        """Read CSV source B."""
        df = pd.read_csv(path)
        # Rename fields according to mapping
        df = self._map_fields(df, {
            'user_id': 'user_id',
            'name': 'name',
            'email_address': 'email',
            'created_at': 'created_date',
            'is_active': 'status',
        })
        df['source'] = 'source_b'
        return df

    def read_source_c(self, path: str) -> pd.DataFrame:
        """Read Parquet source C."""
        df = pd.read_parquet(path)
        # Rename fields according to mapping
        df = self._map_fields(df, {
            'userId': 'user_id',
            'userName': 'name',
            'email': 'email',
            'joined': 'created_date',
            'active': 'status',
        })
        df['source'] = 'source_c'
        return df

    def _map_fields(self, df: pd.DataFrame, mapping: Dict[str, str]) -> pd.DataFrame:
        """Rename fields according to mapping, preserving unmapped columns."""
        df = df.rename(columns=mapping)
        return df

    def _normalize_date(self, date_val: Any) -> str:
        """Normalize date to YYYY-MM-DD format."""
        if pd.isna(date_val) or date_val is None:
            return None

        # If already string in correct format, return as is
        if isinstance(date_val, str):
            try:
                # Parse and reformat to ensure consistency
                dt = datetime.strptime(date_val, '%Y-%m-%d')
                return dt.strftime('%Y-%m-%d')
            except ValueError:
                # Try other common formats
                try:
                    dt = datetime.fromisoformat(str(date_val))
                    return dt.strftime('%Y-%m-%d')
                except:
                    return str(date_val)

        # If timestamp or datetime, convert to string
        if isinstance(date_val, pd.Timestamp):
            return date_val.strftime('%Y-%m-%d')

        return str(date_val)

    def _normalize_status(self, status_val: Any) -> str:
        """Normalize status field."""
        if pd.isna(status_val) or status_val is None:
            return None

        # Handle boolean values
        if isinstance(status_val, bool):
            return 'active' if status_val else 'inactive'

        # Handle string representations of boolean
        if isinstance(status_val, str):
            if status_val.lower() in ['true', '1', 'active', 'yes']:
                return 'active'
            elif status_val.lower() in ['false', '0', 'inactive', 'no']:
                return 'inactive'

        return str(status_val)

    def merge(self, source_a_path: str, source_b_path: str, source_c_path: str):
        """Merge all sources with priority-based conflict resolution."""
        # Read all sources
        print("Reading source files...")
        self.source_data['source_a'] = self.read_source_a(source_a_path)
        self.source_data['source_b'] = self.read_source_b(source_b_path)
        self.source_data['source_c'] = self.read_source_c(source_c_path)

        print(f"  source_a: {len(self.source_data['source_a'])} users")
        print(f"  source_b: {len(self.source_data['source_b'])} users")
        print(f"  source_c: {len(self.source_data['source_c'])} users")

        # Collect all user_ids
        all_user_ids = set()
        for source in ['source_a', 'source_b', 'source_c']:
            all_user_ids.update(self.source_data[source]['user_id'].astype(int).unique())

        print(f"Total unique users: {len(all_user_ids)}")

        # Process each user with priority
        for user_id in sorted(all_user_ids):
            self._merge_user(user_id)

        return self.users

    def _merge_user(self, user_id: int):
        """Merge data for a single user across sources with priority."""
        merged_record = {'user_id': user_id}
        source_values = {source: {} for source in self.SOURCE_PRIORITY}

        # Collect data from all sources for this user
        for source in self.SOURCE_PRIORITY:
            df = self.source_data[source]
            user_data = df[df['user_id'].astype(int) == user_id]

            if len(user_data) > 0:
                row = user_data.iloc[0]
                source_values[source] = {
                    'name': row.get('name'),
                    'email': row.get('email'),
                    'created_date': row.get('created_date'),
                    'status': row.get('status'),
                }

        # Build merged record using priority
        output_fields = ['name', 'email', 'created_date', 'status']

        for field in output_fields:
            for source in self.SOURCE_PRIORITY:
                value = source_values[source].get(field)

                # Skip None/NaN values
                if pd.isna(value) or value is None:
                    continue

                # Normalize specific fields
                if field == 'created_date':
                    value = self._normalize_date(value)
                elif field == 'status':
                    value = self._normalize_status(value)

                # Check if this is a conflict (different values in other sources)
                has_conflict = False
                source_list = {}

                for check_source in self.SOURCE_PRIORITY:
                    check_value = source_values[check_source].get(field)
                    if pd.isna(check_value) or check_value is None:
                        continue

                    # Normalize for comparison
                    if field == 'created_date':
                        check_value = self._normalize_date(check_value)
                    elif field == 'status':
                        check_value = self._normalize_status(check_value)

                    source_list[check_source] = check_value

                # Detect conflict
                if len(source_list) > 1 and len(set(str(v) for v in source_list.values())) > 1:
                    has_conflict = True
                    self.conflicts.append({
                        'user_id': user_id,
                        'field': field,
                        'values': source_list,
                        'selected': value,
                    })

                merged_record[field] = value
                break

        self.users[user_id] = merged_record

    def save_merged_data(self, output_path: str):
        """Save merged users to Parquet format."""
        records = []
        for user_id, data in sorted(self.users.items()):
            records.append(data)

        df = pd.DataFrame(records)

        # Ensure correct data types
        df['user_id'] = df['user_id'].astype('int64')
        df = df[['user_id', 'name', 'email', 'created_date', 'status']]

        df.to_parquet(output_path, index=False)
        print(f"✓ Saved merged data: {output_path}")
        print(f"  {len(df)} users, columns: {', '.join(df.columns.tolist())}")

    def save_conflict_report(self, output_path: str):
        """Save conflict report to JSON."""
        report = {
            'total_conflicts': len(self.conflicts),
            'conflicts': self.conflicts,
        }

        with open(output_path, 'w') as f:
            json.dump(report, f, indent=2)

        print(f"✓ Saved conflict report: {output_path}")
        if self.conflicts:
            print(f"  {len(self.conflicts)} conflicts detected:")
            for conflict in self.conflicts:
                print(f"    - user {conflict['user_id']}, field '{conflict['field']}'")
        else:
            print("  No conflicts detected")


def main():
    """Main entry point."""
    merger = UserMerger()

    print("=== User Data Merge ===\n")

    # Merge sources
    merger.merge(
        '/data/source_a/users.json',
        '/data/source_b/users.csv',
        '/data/source_c/users.parquet',
    )

    print("\nMerging complete!")
    print(f"  Merged {len(merger.users)} unique users\n")

    # Save outputs
    merger.save_merged_data('/app/merged_users.parquet')
    merger.save_conflict_report('/app/conflicts.json')

    print("\n=== Complete ===")


if __name__ == '__main__':
    main()

