"""
Merge user data from three sources with different formats and schemas.
Handles field mapping, priority-based conflict resolution, and conflict reporting.
"""

import json
import csv
from datetime import datetime
import pandas as pd
from pathlib import Path
from typing import Dict, List, Tuple, Any


class UserMerger:
    """Merges user data from multiple sources with priority-based conflict resolution."""

    # Field mapping: source field names -> unified field names
    FIELD_MAPPINGS = {
        'user_id': ['user_id', 'id', 'userId'],
        'name': ['name', 'full_name', 'userName'],
        'email': ['email', 'email_address'],
        'created_date': ['created_date', 'registration_date', 'created_at', 'joined'],
        'status': ['status', 'is_active', 'active'],
    }

    SOURCE_PRIORITY = ['source_a', 'source_b', 'source_c']

    def __init__(self):
        self.users: Dict[int, Dict[str, Any]] = {}
        self.source_data: Dict[str, pd.DataFrame] = {}
        self.conflicts: List[Dict[str, Any]] = []

    def read_source_a(self, path: str) -> pd.DataFrame:
        """Read JSON source A."""
        with open(path, 'r') as f:
            data = json.load(f)
        df = pd.DataFrame(data)
        # Rename fields according to mapping
        df = self._map_fields(df, {
            'id': 'user_id',
            'full_name': 'name',
            'email': 'email',
            'registration_date': 'created_date',
        })
        df['source'] = 'source_a'
        return df

    def read_source_b(self, path: str) -> pd.DataFrame:
        """Read CSV source B."""
        df = pd.read_csv(path)
        # Rename fields according to mapping
        df = self._map_fields(df, {
            'user_id': 'user_id',
            'name': 'name',
            'email_address': 'email',
            'created_at': 'created_date',
            'is_active': 'status',
        })
        df['source'] = 'source_b'
        return df

    def read_source_c(self, path: str) -> pd.DataFrame:
        """Read Parquet source C."""
        df = pd.read_parquet(path)
        # Rename fields according to mapping
        df = self._map_fields(df, {
            'userId': 'user_id',
            'userName': 'name',
            'email': 'email',
            'joined': 'created_date',
            'active': 'status',
        })
        df['source'] = 'source_c'
        return df

    def _map_fields(self, df: pd.DataFrame, mapping: Dict[str, str]) -> pd.DataFrame:
        """Rename fields according to mapping, preserving unmapped columns."""
        df = df.rename(columns=mapping)
        return df

    def _normalize_date(self, date_val: Any) -> str:
        """Normalize date to YYYY-MM-DD format."""
        if pd.isna(date_val) or date_val is None:
            return None

        # If already string in correct format, return as is
        if isinstance(date_val, str):
            try:
                # Parse and reformat to ensure consistency
                dt = datetime.strptime(date_val, '%Y-%m-%d')
                return dt.strftime('%Y-%m-%d')
            except ValueError:
                # Try other common formats
                try:
                    dt = datetime.fromisoformat(str(date_val))
                    return dt.strftime('%Y-%m-%d')
                except:
                    return str(date_val)

